using System.Collections.Concurrent;
using System.ComponentModel;

namespace Slint.Generated;

/// <summary>Converts between the types of generated code and the values of <see cref="ComponentInstance"/>.</summary>
/// <remarks>Code generated by <c>slint-compiler -f csharp</c> calls this; you don't need to.</remarks>
[EditorBrowsable(EditorBrowsableState.Never)]
public static class Conversion
{
    private static readonly ConcurrentDictionary<Type, Func<object, object?>> s_toSlint = new();

    internal static class From<T>
    {
        public static Func<object?, T>? Convert;
    }

    /// <summary>Registers the conversions of a generated struct or enum.</summary>
    public static void Register<T>(Func<T, object?> toSlint, Func<object?, T> fromSlint)
        where T : notnull
    {
        s_toSlint[typeof(T)] = value => toSlint((T)value);
        From<T>.Convert = fromSlint;
    }

    /// <summary>Registers the conversion of a model property with rows of <typeparamref name="T"/>.</summary>
    public static void RegisterModel<T>() =>
        From<Model<T>>.Convert = value => value switch
        {
            Model<T> model => model,
            Model<object?> model => new ConvertedModel<T>(model),
            _ => throw new InvalidCastException($"Can't convert {value?.GetType().Name ?? "null"} to Model<{typeof(T).Name}>"),
        };

    /// <summary>Converts a value returned by <see cref="ComponentInstance"/> to <typeparamref name="T"/>.</summary>
    public static T FromSlint<T>(object? value) => ValueConverter.ConvertTo<T>(value);

    /// <summary>Returns the field <paramref name="name"/> of <paramref name="value"/>, or <c>null</c> if there's none.</summary>
    public static object? Field(Struct value, string name) => value.TryGetValue(name, out var field) ? field : null;

    /// <summary>Converts <paramref name="value"/> for <see cref="ComponentInstance"/>.</summary>
    public static object? ToSlint<T>(T value) => value;

    internal static bool TryToSlint(object value, out object? converted)
    {
        if (s_toSlint.TryGetValue(value.GetType(), out var convert))
        {
            converted = convert(value);
            return true;
        }
        converted = null;
        return false;
    }
}

/// <summary>A typed view of a model that Slint created.</summary>
internal sealed class ConvertedModel<T>(Model<object?> rows) : Model<T>
{
    public override int RowCount => rows.RowCount;

    public override T RowData(int row) => Conversion.FromSlint<T>(rows.RowData(row));

    public override void SetRowData(int row, T value) => rows.SetRowData(row, value);

    private protected override nint ToNativeValue() => ((INativeModel)rows).ToNativeValue();
}

/// <summary>The members that generated code expects a component or global to have.</summary>
/// <param name="Properties">The properties and their types.</param>
/// <param name="Callbacks">The callbacks.</param>
/// <param name="Functions">The functions.</param>
[EditorBrowsable(EditorBrowsableState.Never)]
public sealed record ExpectedApi(
    IReadOnlyDictionary<string, ValueType> Properties,
    IReadOnlyList<string> Callbacks,
    IReadOnlyList<string> Functions);

/// <summary>Loads the <c>.slint</c> file of generated code, and checks that it still matches the generated code.</summary>
[EditorBrowsable(EditorBrowsableState.Never)]
public static class GeneratedApi
{
    /// <summary>Compiles <paramref name="path"/>, throwing with the diagnostics if it has errors.</summary>
    public static CompilationResult Load(string path, string? style)
    {
        using var compiler = new Compiler();
        if (style != null)
        {
            compiler.Style = style;
        }
        var result = compiler.BuildFromPath(path);
        if (result.HasErrors)
        {
            var diagnostics = string.Join("\n", result.Diagnostics.Where(d => d.Level == DiagnosticLevel.Error));
            result.Dispose();
            throw new SlintException($"Failed to compile {path}:\n{diagnostics}");
        }
        return result;
    }

    /// <summary>
    /// Creates the component <paramref name="name"/>,
    /// after checking it and <paramref name="globals"/> against the API that the code was generated for.
    /// </summary>
    public static ComponentInstance Create(
        CompilationResult result,
        string generatedFile,
        string name,
        ExpectedApi component,
        IReadOnlyDictionary<string, ExpectedApi> globals)
    {
        using var definition = Check(result, generatedFile, name, component, globals);
        return definition.Create();
    }

    /// <summary>
    /// Like <see cref="Create"/>, but the component reloads <paramref name="path"/> when it changes,
    /// see <see cref="ComponentInstance.CreateLive"/>.
    /// Without live reload in the native library, warns and creates the component once.
    /// </summary>
    public static ComponentInstance CreateLive(
        CompilationResult result,
        string path,
        string? style,
        string generatedFile,
        string name,
        ExpectedApi component,
        IReadOnlyDictionary<string, ExpectedApi> globals)
    {
        using var definition = Check(result, generatedFile, name, component, globals);
        if (!ComponentInstance.LiveReloadAvailable)
        {
            Console.Error.WriteLine($"Slint: the native library can't reload .slint files, so {name} won't reload");
            return definition.Create();
        }
        return ComponentInstance.CreateLive(path, name, style);
    }

    private static ComponentDefinition Check(
        CompilationResult result,
        string generatedFile,
        string name,
        ExpectedApi component,
        IReadOnlyDictionary<string, ExpectedApi> globals)
    {
        var definition = result.Component(name)
            ?? throw new SlintException($"{generatedFile} is out of date: the .slint file no longer exports '{name}'");
        var problems = new List<string>();
        Compare(name, component, definition.Properties, definition.Callbacks, definition.Functions, problems);
        foreach (var (global, expected) in globals)
        {
            var properties = definition.GlobalProperties(global);
            if (properties == null)
            {
                problems.Add($"there's no global '{global}'");
                continue;
            }
            Compare(global, expected, properties, definition.GlobalCallbacks(global)!, definition.GlobalFunctions(global)!, problems);
        }
        if (problems.Count > 0)
        {
            definition.Dispose();
            throw new SlintException($"{generatedFile} is out of date; regenerate it:\n" + string.Join("\n", problems));
        }
        return definition;
    }

    private static void Compare(
        string owner,
        ExpectedApi expected,
        IReadOnlyDictionary<string, ValueType> properties,
        IReadOnlyList<string> callbacks,
        IReadOnlyList<string> functions,
        List<string> problems)
    {
        var actualProperties = properties.ToDictionary(p => Normalize(p.Key), p => p.Value);
        foreach (var (property, type) in expected.Properties)
        {
            if (!actualProperties.TryGetValue(property, out var actual))
            {
                problems.Add($"'{owner}' has no property '{property}'");
            }
            else if (actual != type)
            {
                problems.Add($"property '{property}' of '{owner}' is {actual}, not {type}");
            }
        }
        var actualCallbacks = callbacks.Select(Normalize).ToHashSet();
        problems.AddRange(expected.Callbacks.Where(c => !actualCallbacks.Contains(c)).Select(c => $"'{owner}' has no callback '{c}'"));
        var actualFunctions = functions.Select(Normalize).ToHashSet();
        problems.AddRange(expected.Functions.Where(f => !actualFunctions.Contains(f)).Select(f => $"'{owner}' has no function '{f}'"));
    }

    /// <summary>Matches <c>normalize_identifier</c> in <c>internal/compiler/names.rs</c>.</summary>
    private static string Normalize(string name) =>
        name.Length == 0 ? name : (name[0] == '-' ? '_' : name[0]) + name[1..].Replace('_', '-');
}
